const assert = require('node:assert/strict');
const events = require('../data/events.json');
const people = require('../data/characters.json');
const sources = require('../data/sources.json');
const event = id => events.find(e=>e.id===id);
assert.ok(event('E371-001').characters.includes('P03-P03'));
assert.equal(event('E371-001').character_presence['P03-P03'],'present');
assert.equal(event('E371-001').character_presence['JUD-003'],'remote');
assert.match(event('E371-001').description,/ハシトウがロベリーを押さえて/);
assert.match(event('E371-001').description,/サカタは最高裁判官クレアパトロへ電話/);
assert.equal(event('E372-003').title,'ハンゾーがタフディーを殺害する');
assert.equal(event('E372-003').status_effects[0].status,'死亡');
assert.equal(event('E372-003').verification_status,'unverified');
assert.match(event('E372-003').verification_note,/直接描写はない/);
assert.ok(event('E372-003').revealed_facts.some(s=>/本当に薬を使ったかは確認できない/.test(s)));
assert.ok(!event('E372-003').revealed_facts.some(s=>s==='ナゴマムは薬で眠らされている（ハンゾーの分身の説明）'));
const tafdhi = people.find(p=>p.id==='P12-Q05');
assert.equal(tafdhi.status,'死亡');
assert.equal(tafdhi.status_log[0].event_id,'E372-003');
assert.equal(tafdhi.status_log[0].killer,'P12-H01');
assert.ok(!JSON.stringify(tafdhi).includes('最終ページが未提供'));
assert.ok(!event('E372-009'),'removed unsupported scene must not remain in public events');
assert.match(event('E373-002').title,/私物の焼却を命じる/);
assert.doesNotMatch(event('E373-002').title,/追跡処刑.*命じる/);
assert.ok(event('E373-004').time_estimate < event('E373-006').time_estimate);
assert.ok(event('E373-006').time_estimate < event('E373-005').time_estimate);
assert.equal(event('E373-006').time_before_event_id,'E373-005');
assert.ok(event('E373-006').chapter_order < event('E373-005').chapter_order);
assert.equal(event('E375-002').title,'シカクがハルケンブルグの守護霊獣を分析する');
assert.ok(sources.some(s=>s.id==='user-memo-clock-20261017' && s.source_type==='user_hypothesis'));
for(const [id,clock] of [['E374-005','01:30'],['E375-007','07:30'],['E375-009','07:00']]) {
  assert.equal(event(id).time_start,null,id);
  assert.equal(event(id).time_estimate,clock,id);
  assert.equal(event(id).time_estimate_basis,'user-memo-clock-20261017',id);
}
assert.ok(event('E375-005').time_estimate < event('E375-007').time_estimate);
assert.ok(event('E375-007').time_estimate < event('E375-006').time_estimate);
assert.equal(event('E375-007').time_before_event_id,'E375-006');
assert.ok(!event('E375-007').description.includes('全員で念の修行'));
assert.match(event('E375-006').description,/境界が判明した後.*全員で念の修行/);
console.log('PASS: supplied notes, role attribution, speech versus facts, death consistency, removed scene, order, names and approximate clocks');
